import{z as i,x as l,o as t,c as B,q as r,j as n,D as e,d as o,s,S as A}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"互连与 NUMA","description":"","frontmatter":{"title":"互连与 NUMA","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/interconnect-numa.md","filePath":"cs/interconnect-numa.md","lastUpdated":1791413859000}'),p={name:"cs/interconnect-numa.md"};function d(c,a,m,h,D,_){const E=l("Mermaid");return t(),B("div",null,[a[2]||(a[2]=r('<h1 id="互连与-numa" tabindex="-1">互连与 NUMA <a class="header-anchor" href="#互连与-numa" aria-label="Permalink to &quot;互连与 NUMA&quot;">​</a></h1><div class="epigraph"><p>核多到无法共享一条总线时，内存贴在不同控制器上；本地命中快，远程要走片上或片间互连。</p><footer>—— 据 Hennessy and Patterson, Computer Architecture: A Quantitative Approach 整理</footer></div><p><a href="/cs/tso-weak">上一课</a>把可见性写成模型，并假定「全局可见」有一个大致均匀的延迟。<a href="/cs/multicore-shared-cache">多核与共享缓存</a>用一条抽象互连接到 LLC。<a href="/cs/mesi-protocol">MESI</a>的窥探广播在核数上升时占满总线。本课不重讲 SC。缺口是：物理上内存和目录必须分区，访问时间不再对称。本课只钉互连与 NUMA，体系结构课还剩内存控制器一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>窥探要求每核每拍看见所有事务，带宽和监听过滤都随核数恶化。内存控制器若只有一套，该点成为热点。<a href="/cs/memory-array-sram-dram">SRAM 与 DRAM 阵列</a>已经说明通道有限。缺口不是再加一路 L1，而是<strong>拓扑：交叉开关、环、网格；以及内存附着在不同节点上，形成非一致访存时间</strong>。</p><p>目录协议把「谁有副本」记在主节点，避免广播。本课承认目录是扩展一致性的手段，不把目录项格式写完。</p><p><span class="marginnote">数字实例：本地 DRAM 访问大约 80–100 纳秒，跨互连的远端访问常是它的 1.5–2 倍。一个每拍都摸远端页的热循环，性能直接掉一半——不是缓存没调好，是页放错了节点。</span></p><p><span class="marginnote">NUMA 不是取消共享内存，只是把 load 延迟变成「这页在不在本节点」的函数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>节点 = 若干核 + 本地 DRAM + 目录切片。远程 load：互连转发，目录找到持有者，必要时转发数据。操作系统尽量把页分配在访问多的节点（亲和），否则 CPI 里出现固定的远程项。</p>',10)),(t(),n(A,null,{default:e(()=>[s(E,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20LR%0A%20%20N0%5B%22%E8%8A%82%E7%82%B9%200%20%E6%A0%B8%2B%E5%86%85%E5%AD%98%22%5D%20--%3E%20XBAR%5B%22%E4%BA%92%E8%BF%9E%22%5D%0A%20%20N1%5B%22%E8%8A%82%E7%82%B9%201%20%E6%A0%B8%2B%E5%86%85%E5%AD%98%22%5D%20--%3E%20XBAR%0A%20%20XBAR%20--%3E%20DIR%5B%22%E7%9B%AE%E5%BD%95%2F%E8%BF%9C%E7%A8%8B%E6%95%B0%E6%8D%AE%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p><a href="/cs/locality-principle">局部性原理</a>多了一层：核间局部性（共享行应在目录与 LLC 上命中）和节点局部性（数据放本地 DRAM）。假共享的代价变成跨互连的 MESI 迁移。</p><p><span class="marginnote">直觉类比：NUMA 像一栋写字楼里每层自带文件柜。柜子在你这层（本地节点），起身就取；文件在别的层，要穿走廊（互连）去拿，路远还可能排队等电梯（互连拥塞）。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>顺序一致性或 TSO 仍然可实现，但「全局可见」的物理意义是事务到达目录并完成。栅栏更贵。阿姆达尔：远程比例 \\(f\\) 一旦非零，加核加速被互连封顶。编程上把锁与热点结构放本地，或复制只读。页若落在远端节点，<a href="/cs/locality-principle">局部性原理</a>的命中仍可能付跨互连的常数。</p><p>一次 load 走本地还是走远端，路径差在页落在哪个节点。</p>',5)),(t(),n(A,null,{default:e(()=>[s(E,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E6%A0%B8%E5%8F%91%E8%B5%B7%20load%22%5D%20--%3E%20Q1%7B%22%E9%A1%B5%E5%9C%A8%E6%9C%AC%E8%8A%82%E7%82%B9%20DRAM%3F%22%7D%0A%20%20Q1%20--%3E%7C%22%E6%98%AF%22%7C%20LC%5B%22%E6%9C%AC%E5%9C%B0%E5%86%85%E5%AD%98%E6%8E%A7%E5%88%B6%E5%99%A8%22%5D%0A%20%20LC%20--%3E%20D1%5B%22%E6%9C%AC%E5%9C%B0%E5%BB%B6%E8%BF%9F%E8%BF%94%E5%9B%9E%22%5D%0A%20%20Q1%20--%3E%7C%22%E5%90%A6%22%7C%20HOP%5B%22%E8%B7%A8%E4%BA%92%E8%BF%9E%E5%88%B0%E8%BF%9C%E7%AB%AF%E8%8A%82%E7%82%B9%22%5D%0A%20%20HOP%20--%3E%20D2%5B%22%E7%9B%AE%E5%BD%95%E5%AE%9A%E4%BD%8D%E5%B9%B6%E8%BD%AC%E5%8F%91%E6%95%B0%E6%8D%AE%22%5D%0A%20%20D2%20--%3E%20D3%5B%22%E5%BB%B6%E8%BF%9F%E6%88%90%E5%80%8D%EF%BC%8C%E8%BF%98%E5%8D%A0%E4%BA%92%E8%BF%9E%E5%B8%A6%E5%AE%BD%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<p><span class="marginnote">常见误区：初学者容易把 NUMA 读成「各节点各管各的内存、互相看不见」；实际上地址空间仍是全局统一的，任何核都能访问任何地址——变的只是延迟分档，不是可见性。</span></p><p>体系结构主干只剩内存控制器收尾：指令能在流水线里跑，存储器层次、一致性和距离都有了名字。还没有给程序员一套与 ISA 无关的「表、栈、图」布局约定——那是后面数据结构课的缺口。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不进入网络课的路由拥塞控制，不把 QPI/UPI 型号当正文。也不把 NUMA 写成「没有共享内存」：地址仍全局，只是延迟分档。GPU 多设备互连不在本栏展开。</p><p>后课默认：访存延迟依赖页在哪一节点。数据结构课开始时，假定这些指令与层次已经会执行。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>总线窥探不可任意扩展；目录加互连分区内存。</li><li>NUMA：同一物理地址，本地与远程延迟不同。</li><li>体系结构课还剩内存控制器收尾；比特布局的命名留给后面的数据结构课。</li><li>地址仍全局共享；NUMA 只把延迟分档。</li><li>出处：Hennessy and Patterson, <em>CA:AQA</em> 互连与目录一致性。</li></ul>',7))])}const f=i(p,[["render",d]]);export{C as __pageData,f as default};
